pub fn execute(command: &str, options: &CommandOptions) -> Result<CommandResult> {
    let start = Instant::now();

    // ... setup code ...

    // Convert execution errors to BivvyError
    let output = cmd.output().map_err(|_| BivvyError::CommandFailed {
        command: command.to_string(),
        code: None,  // None when process never spawned
    })?;

    // ... capture output ...

    if output.status.success() {
        Ok(CommandResult::success(stdout, stderr, duration))
    } else {
        // Failure: still returns Ok(CommandResult::failure(...))
        Ok(CommandResult::failure(
            output.status.code(),  // Some(exit_code) or None
            stdout,
            stderr,
            duration,
        ))
    }
}
```

**Key Design**: Command failures are NOT errors, they're captured results

