176→    /// Check whether the network is reachable.
177→    ///
178→    /// Attempts a TCP connection to a well-known host with a 2-second timeout.
179→    /// Returns `true` if the connection succeeds, `false` otherwise.
180→    pub fn check_network(&self) -> bool {
181→        // Try multiple well-known hosts to reduce false negatives
182→        const TARGETS: &[(&str, u16)] = &[
183→            ("1.1.1.1", 443), // Cloudflare DNS
184→            ("8.8.8.8", 443), // Google DNS
185→            ("9.9.9.9", 443), // Quad9 DNS
186→        ];
187→        let timeout = Duration::from_secs(2);
188→
189→        for &(host, port) in TARGETS {
190→            let addr = format!("{}:{}", host, port);
191→            if let Ok(addr) = addr.parse() {
192→                if TcpStream::connect_timeout(&addr, timeout).is_ok() {
193→                    return true;
194→                }
195→            }
196→        }
197→        false
198→    }
199→
200→    fn evaluate(&self, requirement: &str) -> RequirementStatus {
201→        let Some(req) = self.registry.get(requirement) else {
202→            return RequirementStatus::Unknown;
203→        };
204→
205→        for check in &req.checks {
206→            if let Some(status) = self.evaluate_check(check, req) {
207→                return status;
208→            }
209→        }
210→
211→        // No check matched — Missing
212→        RequirementStatus::Missing {
213→            install_template: req.install_template.clone(),
214→            install_hint: req.install_hint.clone(),
215→        }
216→    }
217→
218→    fn evaluate_check(
219→        &self,
220→        check: &RequirementCheck,
221→        req: &crate::requirements::registry::Requirement,
222→    ) -> Option<RequirementStatus> {
223→        match check {
224→            RequirementCheck::CommandSucceeds(cmd) => {
225→                if self.run_command_succeeds(cmd) {
226→                    Some(RequirementStatus::Satisfied)
227→                } else {
228→                    None
229→                }
230→            }
231→            RequirementCheck::FileExists(path) => {
232→                let full_path = if Path::new(path).is_absolute() {
233→                    PathBuf::from(path)
234→                } else {
235→                    self.project_root.join(path)
236→                };
237→                if full_path.exists() {
238→                    Some(RequirementStatus::Satisfied)
239→                } else {
240→                    None
241→                }
242→            }
243→            RequirementCheck::ServiceReachable(cmd) => {
244→                if self.run_command_succeeds(cmd) {
245→                    Some(RequirementStatus::Satisfied)
246→                } else {
247→                    // Service check is the main/only check — return ServiceDown
248→                    Some(RequirementStatus::ServiceDown {
249→                        binary_present: self.check_binary_present(cmd),
250→                        install_template: req.install_template.clone(),
251→                        start_command: None,
252→                        start_hint: req
253→                            .install_hint
254→                            .clone()
255→                            .unwrap_or_else(|| format!("Start the {} service", req.name)),
256→                    })
257→                }
258→            }
259→            RequirementCheck::ManagedCommand {
260→                command: tool,
261→                managed_path_patterns,
262→                system_path_patterns,
263→                version_file,
264→            } => self.evaluate_managed_command(
265→                tool,
266→                managed_path_patterns,
267→                system_path_patterns,
268→                version_file.as_deref(),
269→                req,
270→            ),
271→            RequirementCheck::Any(sub_checks) => {
272→                for sub in sub_checks {
273→                    if let Some(status) = self.evaluate_check(sub, req) {
274→                        if status.is_satisfied() || status.can_proceed() {
275→                            return Some(status);
276→                        }
277→                    }
278→                }
279→                None
280→            }
281→        }
282→    }
