  1→//! Template inputs validation.
  2→//!
  3→//! This rule validates that required template inputs are provided
  4→//! and that input types match their contracts.
  5→
  6→use crate::config::BivvyConfig;
  7→use crate::lint::{LintDiagnostic, LintRule, RuleId, Severity};
  8→use crate::registry::Registry;
  9→
 10→/// Validates template inputs match contracts.
 11→pub struct TemplateInputsRule {
 12→    registry: Registry,
 13→}
 14→
 15→impl TemplateInputsRule {
 16→    /// Create a new template inputs rule with the given registry.
 17→    pub fn new(registry: Registry) -> Self {
 18→        Self { registry }
 19→    }
 20→}
 21→
 22→impl LintRule for TemplateInputsRule {
 23→    fn id(&self) -> RuleId {
 24→        RuleId::new("template-inputs")
 25→    }
 26→
 27→    fn name(&self) -> &str {
 28→        "Template Inputs"
 29→    }
 30→
 31→    fn description(&self) -> &str {
 32→        "Validates template input contracts are satisfied"
 33→    }
 34→
 35→    fn default_severity(&self) -> Severity {
 36→        Severity::Error
 37→    }
 38→
 39→    fn check(&self, config: &BivvyConfig) -> Vec<LintDiagnostic> {
 40→        let mut diagnostics = Vec::new();
 41→
 42→        for (step_name, step_config) in &config.steps {
 43→            if let Some(ref template_name) = step_config.template {
 44→                if let Some(template) = self.registry.get(template_name) {
 45→                    // Check for missing required inputs
 46→                    for (input_name, input_contract) in &template.inputs {
 47→                        if input_contract.required
 48→                            && input_contract.default.is_none()
 49→                            && !step_config.inputs.contains_key(input_name)
 50→                        {
 51→                            diagnostics.push(LintDiagnostic::new(
 52→                                self.id(),
 53→                                self.default_severity(),
 54→                                format!(
 55→                                    "Step '{}' is missing required input '{}' for template '{}'",
 56→                                    step_name, input_name, template_name
 57→                                ),
 58→                            ));
 59→                        }
 60→
 61→                        // Validate provided inputs
 62→                        if let Some(value) = step_config.inputs.get(input_name) {
 63→                            if let Err(err) = input_contract.validate(input_name, Some(value)) {
 64→                                diagnostics.push(LintDiagnostic::new(
 65→                                    self.id(),
 66→                                    self.default_severity(),
 67→                                    format!("Step '{}': {}", step_name, err),
 68→                                ));
 69→                            }
 70→                        }
 71→                    }
 72→
 73→                    // Check for unknown inputs
 74→                    for input_name in step_config.inputs.keys() {
 75→                        if !template.inputs.contains_key(input_name) {
 76→                            diagnostics.push(LintDiagnostic::new(
 77→                                self.id(),
 78→                                Severity::Warning,
 79→                                format!(
 80→                                    "Step '{}' provides unknown input '{}' for template '{}'",
 81→                                    step_name, input_name, template_name
 82→                                ),
 83→                            ));
 84→                        }
 85→                    }
 86→                }
 87→            }
 88→        }
 89→
 90→        diagnostics
 91→    }
 92→}
